let questions=brandQuestions,sections=brandSections;
const key='karrun_briefing_v1';let state={index:0,answers:{},profile:{}};const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function setProject(type){const system=type==='system';questions=system?systemQuestions:brandQuestions;sections=system?systemSections:brandSections} function load(){try{const saved=JSON.parse(localStorage.getItem(key));if(saved)state={...state,...saved}}catch{} setProject(state.profile.type||'brand');$('#project-type').value=state.profile.type||'brand';$('#resume-briefing').hidden=!Object.keys(state.answers).length}
function save(){localStorage.setItem(key,JSON.stringify(state))}
function profile(){const type=$('#project-type').value;const changed=state.profile.type&&state.profile.type!==type;state.profile={name:$('#client-name').value.trim(),company:$('#client-company').value.trim(),email:$('#client-email').value.trim(),type};if(changed){state.index=0;state.answers={}}setProject(type);if(!state.profile.name||!state.profile.company){alert('Preencha seu nome e o nome da marca para começar.');return false}save();return true}
function start(resume=false){if(!resume&&!profile())return;if(resume)setProject(state.profile.type||'brand');document.body.classList.add('briefing-active');$('#briefing-intro').hidden=true;$('#briefing-done').hidden=true;$('#briefing-shell').hidden=false;render()}
function render(){const item=questions[state.index],saved=state.answers[state.index];$('#section-label').textContent=`${String(item.section+1).padStart(2,'0')} / ${sections[item.section]}`;$('#question-title').textContent=item.title;$('#question-help').textContent=item.help||'';$('#progress-label').textContent=`Pergunta ${state.index+1} de ${questions.length}`;$('#progress-bar').style.width=`${((state.index+1)/questions.length)*100}%`;$('#previous-question').disabled=state.index===0;$('#next-question').textContent=state.index===questions.length-1?'Concluir briefing':'Continuar →';$('#briefing-error').textContent='';const a=$('#answer-area');
if(item.type==='text'||item.type==='textarea')a.innerHTML=item.type==='textarea'?`<textarea class="briefing-input" id="current-answer" rows="6" placeholder="Escreva com suas palavras…">${esc(saved||'')}</textarea>`:`<input class="briefing-input" id="current-answer" value="${esc(saved||'')}" placeholder="Digite sua resposta…">`;
else if(item.type==='single'||item.type==='multi'){const vals=Array.isArray(saved)?saved:[saved].filter(Boolean);a.innerHTML=`<div class="choice-grid">${item.options.map(o=>`<label class="choice"><input type="${item.type==='single'?'radio':'checkbox'}" name="choice" value="${esc(o)}" ${vals.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div>`}
else if(item.type==='fields'){const obj=saved||{};a.innerHTML=`<div class="briefing-fields">${item.options.map(o=>`<label>${esc(o)}<input data-field="${esc(o)}" value="${esc(obj[o]||'')}"></label>`).join('')}</div>`}
else {const obj=saved||{};a.innerHTML=`<div class="briefing-fields"><label>Links e observações<textarea id="reference-links" rows="7" placeholder="Cole um link por linha e conte o que chamou sua atenção.">${esc(obj.text||'')}</textarea></label><label class="file-field">Selecionar imagens ou arquivos<input id="reference-files" type="file" multiple accept="image/*,.pdf"></label><p class="small" id="file-list">${esc((obj.files||[]).join(', '))}</p></div>`}}
function capture(){const item=questions[state.index],a=$('#answer-area');if(item.type==='text'||item.type==='textarea')state.answers[state.index]=a.querySelector('#current-answer').value.trim();else if(item.type==='single'||item.type==='multi'){const vals=[...a.querySelectorAll('input:checked')].map(i=>i.value);if(item.max&&vals.length>item.max){$('#briefing-error').textContent=`Escolha no máximo ${item.max} opções.`;return false}state.answers[state.index]=item.type==='single'?(vals[0]||''):vals}else if(item.type==='fields'){state.answers[state.index]=Object.fromEntries([...a.querySelectorAll('[data-field]')].map(i=>[i.dataset.field,i.value.trim()]))}else{const files=[...(a.querySelector('#reference-files').files||[])].map(f=>f.name);state.answers[state.index]={text:a.querySelector('#reference-links').value.trim(),files:files.length?files:(state.answers[state.index]?.files||[])} }save();return true}
function next(){if(!capture())return;if(state.index<questions.length-1){state.index++;save();render();scrollTo({top:0,behavior:'smooth'})}else finish()}
function formatAnswer(v){if(Array.isArray(v))return v.join(', ');if(v&&typeof v==='object')return Object.entries(v).filter(([,x])=>x&&(Array.isArray(x)?x.length:true)).map(([k,x])=>`${k}: ${Array.isArray(x)?x.join(', '):x}`).join(' | ');return v||'—'}
function fullText(){return [`BRIEFING — ${state.profile.company}`,`Cliente: ${state.profile.name}`,state.profile.email&&`E-mail: ${state.profile.email}`,`Tipo de projeto: ${state.profile.type==='system'?'Sistema ou software':'Identidade visual e loja virtual'}`,'',...questions.map((x,i)=>`${i+1}. ${x.title}\n${formatAnswer(state.answers[i])}`)].filter(x=>x!==false).join('\n\n')}
function finish(){save();document.body.classList.add('briefing-active');$('#briefing-shell').hidden=true;$('#briefing-done').hidden=false;$('#done-name').textContent=state.profile.name.split(' ')[0];$('#briefing-summary').innerHTML=`<strong>${esc(state.profile.company)}</strong><span>${Object.values(state.answers).filter(v=>formatAnswer(v)!=='—').length} de ${questions.length} respostas registradas</span>`;scrollTo({top:0,behavior:'smooth'})}
let autoSaveTimer;$('#answer-area').addEventListener('input',()=>{clearTimeout(autoSaveTimer);autoSaveTimer=setTimeout(capture,250)});$('#answer-area').addEventListener('change',capture);
$('#start-briefing').addEventListener('click',()=>start(false));$('#resume-briefing').addEventListener('click',()=>start(true));$('#next-question').addEventListener('click',next);$('#previous-question').addEventListener('click',()=>{capture();if(state.index){state.index--;save();render()}});$('#skip-question').addEventListener('click',()=>{state.answers[state.index]??='';next()});$('#save-exit').addEventListener('click',()=>{capture();document.body.classList.remove('briefing-active');$('#briefing-shell').hidden=true;$('#briefing-intro').hidden=false;$('#resume-briefing').hidden=false;scrollTo({top:0,behavior:'smooth'})});$('#send-briefing').addEventListener('click',()=>open(`https://wa.me/5544988211479?text=${encodeURIComponent(fullText())}`,'_blank','noopener'));$('#download-briefing').addEventListener('click',()=>{const blob=new Blob([fullText()],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`briefing-${state.profile.company.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.txt`;a.click();URL.revokeObjectURL(a.href)});$('#edit-briefing').addEventListener('click',()=>{state.index=0;start(true)});load();
